lv_obj_t *zmk_display_status_screen() {
    lv_obj_t *screen;
    screen = lv_obj_create(NULL);

    // ---------------------------------------------------------
    // MÀN HÌNH CHÍNH (Bên Trái) - PIN iPHONE & KẾT NỐI
    // ---------------------------------------------------------
    #if IS_ENABLED(CONFIG_ZMK_DISPLAY_STATUS_SCREEN_BUILT_IN)
        
        // 1. Biểu tượng Pin kiểu iPhone (Vẽ khung)
        lv_obj_t *bat_body = lv_obj_create(screen);
        lv_obj_set_size(bat_body, 28, 14);
        lv_obj_align(bat_body, LV_ALIGN_TOP_LEFT, 2, 2);
        lv_obj_set_style_border_width(bat_body, 1, 0);
        lv_obj_set_style_radius(bat_body, 2, 0);
        lv_obj_set_style_pad_all(bat_body, 0, 0);

        // Đầu cực dương pin
        lv_obj_t *bat_tip = lv_obj_create(screen);
        lv_obj_set_size(bat_tip, 2, 6);
        lv_obj_align_to(bat_tip, bat_body, LV_ALIGN_OUT_RIGHT_MID, 0, 0);
        lv_obj_set_style_bg_color(bat_tip, lv_color_white(), 0);

        // Số % pin nằm trong viên pin (Ví dụ 90)
        lv_obj_t *bat_label = lv_label_create(bat_body);
        lv_label_set_text(bat_label, "90"); 
        lv_obj_center(bat_label);

        // 2. Trạng thái kết nối (USB/Bluetooth)
        lv_obj_t *conn_label = lv_label_create(screen);
        // Hiển thị đơn giản (ZMK sẽ tự động cập nhật nếu bạn dùng Widget thật, 
        // ở đây mình dùng text để bạn dễ căn chỉnh tọa độ trước)
        lv_label_set_text(conn_label, "CONN: BLE 1"); 
        lv_obj_align(conn_label, LV_ALIGN_BOTTOM_LEFT, 2, -2);

        // 3. Trạng thái kết nối với bên phụ (Split Link)
        lv_obj_t *split_label = lv_label_create(screen);
        lv_label_set_text(split_label, "SPLIT: OK"); 
        lv_obj_align(split_label, LV_ALIGN_BOTTOM_RIGHT, -2, -2);

    // ---------------------------------------------------------
    // MÀN HÌNH PHỤ (Bên Phải) - LOGO MCOI
    // ---------------------------------------------------------
    #else
        lv_obj_t *img = lv_img_create(screen);
        lv_img_set_src(img, &mcoi_logo_dsc);
        lv_obj_align(img, LV_ALIGN_CENTER, 0, 0);
    #endif

    return screen;
}
